'use strict';
(function(root){
 const stop=new Set('the a an of to in and or on for with by from as is are was were be been it its this that these those at but not which what how according paragraph text directions english section read following answer sheet points choose best year questions question your you he she they their his her'.split(' '));
 const tokens=text=>(String(text).toLowerCase().replace(/([a-z])-\s*\n\s*([a-z])/g,'$1$2').match(/[a-z]+(?:'[a-z]+)?/g)||[]);
 function features(text){const ts=tokens(text),f=new Set();for(let i=0;i<ts.length;i++){const t=ts[i];if(t.length>=3&&!stop.has(t))f.add('w:'+t);if(i&&ts[i-1].length>1&&t.length>1&&(!stop.has(t)||!stop.has(ts[i-1])))f.add('b:'+ts[i-1]+' '+t);if(i>1&&(!stop.has(t)||!stop.has(ts[i-1])))f.add('t:'+ts[i-2]+' '+ts[i-1]+' '+t)}return f}
 function build(pages){const docs=pages.map(p=>({page:p,features:features(p.text)})),df=new Map();for(const d of docs)for(const f of d.features)df.set(f,(df.get(f)||0)+1);return {docs,df}}
 function rank(text,index,limit=5){const f=features(text),weighted=[...f].filter(x=>index.df.has(x)).map(x=>[x,(x[0]==='t'?2:x[0]==='b'?1.4:.65)*Math.log(1+index.docs.length/index.df.get(x))]);const total=weighted.reduce((s,[,w])=>s+w,0);if(!total)return [];return index.docs.map(d=>{let score=0,shared=0,phrases=0;for(const [key,w]of weighted)if(d.features.has(key)){score+=w;shared++;if(key[0]!=='w')phrases++}return {page:d.page,score:score/total,shared,phrases}}).filter(x=>x.shared).sort((a,b)=>b.score-a.score||b.phrases-a.phrases).slice(0,limit)}
 function decide(results){const a=results[0],b=results[1];if(!a)return {accepted:false,reason:'没有匹配内容'};const margin=a.score-(b?.score||0);const accepted=a.score>=.48&&a.shared>=16&&a.phrases>=8&&margin>=.12;return {accepted,margin,reason:accepted?'已自动对应':a.shared<16||a.phrases<8?'可识别内容太少，请拍摄题干或完整文章':margin<.12?'候选接近，请核对后选择':'匹配不足，请核对候选或补充资料'}}
 function align(ocr,reference){const norm=t=>String(t).toLowerCase().replace(/[^a-z0-9]/g,''),a=ocr.map(w=>norm(w.text)),b=reference.map(w=>norm(w.text));if(a.length>2500||b.length>2500)return ocr.map(w=>({...w,index:null}));const width=b.length+1,dp=new Uint16Array((a.length+1)*width);for(let i=a.length-1;i>=0;i--)for(let j=b.length-1;j>=0;j--)dp[i*width+j]=a[i]&&a[i]===b[j]?dp[(i+1)*width+j+1]+1:Math.max(dp[(i+1)*width+j],dp[i*width+j+1]);const out=ocr.map(w=>({...w,index:null}));let i=0,j=0;while(i<a.length&&j<b.length){if(a[i]&&a[i]===b[j]){out[i].index=j;i++;j++}else if(dp[(i+1)*width+j]>=dp[i*width+j+1])i++;else j++}return out}
 function references(text,pages,limit=3,question=null){
  const out=rank(text,build(pages),pages.length);
  if(question&&question<=20){const readingStart=pages.find(p=>(p.questionNumbers||[]).some(n=>n>=21&&n<=25))?.page||10;const anchored=pages.filter(p=>p.page<=readingStart&&(p.questionNumbers||[]).includes(question)).sort((a,b)=>b.page-a.page);if(anchored.length)return anchored.slice(0,limit).map(p=>({page:p,score:1,shared:0,phrases:0,anchor:true}))}
  if(question>=21&&question<=45)for(const r of out){const nums=(r.page.questionNumbers||[]).filter(n=>n>=21&&n<=45);if(nums.length>=4)r.score*=.5;else if(nums.includes(question))r.score=r.score*1.4+.08;else if(nums.length)r.score*=.8}
  return out.filter(x=>x.phrases>=2&&x.shared>=5).sort((a,b)=>b.score-a.score||b.page.page-a.page.page).slice(0,limit)
 }
 function orientation(words,width,height){const long=words.filter(w=>tokens(w.text).join('').length>=4);const vertical=long.filter(w=>w.h*height>w.w*width*1.3).length>long.length*.55;let forward=0,back=0;for(let i=1;i<words.length;i++){const a=words[i-1],b=words[i],dx=b.x+b.w/2-a.x-a.w/2,dy=b.y+b.h/2-a.y-a.h/2;if(vertical?Math.abs(dx)<2.5&&Math.abs(dy)>1:Math.abs(dy)<1&&Math.abs(dx)>1){if((vertical?dy:dx)>0)forward++;else back++}}if(forward+back<8)return 0;if(vertical)return forward>back?270:90;return back>forward*1.8?180:0}
 function rotateBoxes(words,angle){return words.map(w=>{if(angle===90)return {...w,x:100-w.y-w.h,y:w.x,w:w.h,h:w.w};if(angle===270)return {...w,x:w.y,y:100-w.x-w.w,w:w.h,h:w.w};if(angle===180)return {...w,x:100-w.x-w.w,y:100-w.y-w.h};return {...w}})}
 function questionFromPhoto(words,page){const allowed=new Set((page.questions||[]).map(q=>q.number));for(const w of words){const m=String(w.text).match(/^(\d{1,2})[.．:：]?$/);if(m&&allowed.has(Number(m[1])))return Number(m[1])}if(allowed.size>1){const ranked=rank(words.map(w=>w.text).join(' '),build(page.questions.map(q=>({id:q.number,text:q.text}))));if(decide(ranked).accepted)return ranked[0].page.id}return null}
 root.ExamMatch={tokens,features,build,rank,decide,align,references,orientation,rotateBoxes,questionFromPhoto};
})(globalThis);
